// Amazon font @font-face rules, generated at build time.
//
// The woff2 files in public/fonts/amazon-ember/ are generated by
// `npm run assets:fonts` from the Amazon type library package in fonts/. Faces whose
// file is missing declare local() sources only, so visitors who have the font
// installed get it and everyone else falls back to Arial, with no 404s.
import { existsSync } from 'node:fs';
import { join } from 'node:path';

const DIR = 'fonts/amazon-ember';

// Amazon Ember for text and UI, Amazon Ember Display for headings.
const FACES = [
  {
    family: 'Amazon Ember',
    file: 'AmazonEmber_Rg',
    weight: 400,
    style: 'normal',
    preload: true,
    local: ['Amazon Ember', 'AmazonEmber-Regular'],
  },
  {
    family: 'Amazon Ember',
    file: 'AmazonEmber_RgIt',
    weight: 400,
    style: 'italic',
    preload: false,
    local: ['Amazon Ember Italic', 'AmazonEmber-Italic'],
  },
  {
    family: 'Amazon Ember',
    file: 'AmazonEmber_Bd',
    weight: 700,
    style: 'normal',
    preload: true,
    local: ['Amazon Ember Bold', 'AmazonEmber-Bold'],
  },
  {
    family: 'Amazon Ember Display',
    file: 'AmazonEmberDisplay_Bd',
    weight: 700,
    style: 'normal',
    preload: true,
    local: ['Amazon Ember Display Bold', 'AmazonEmberDisplay-Bold'],
  },
];

export function amazonEmber() {
  const preload: string[] = [];
  const css = FACES.map((f) => {
    const url = `/${DIR}/${f.file}.woff2`;
    const hosted = existsSync(join(process.cwd(), 'public', DIR, `${f.file}.woff2`));
    if (hosted && f.preload) preload.push(url);
    const src = [
      ...f.local.map((name) => `local('${name}')`),
      ...(hosted ? [`url('${url}') format('woff2')`] : []),
    ].join(',');
    return `@font-face{font-family:'${f.family}';font-style:${f.style};font-weight:${f.weight};font-display:swap;src:${src}}`;
  }).join('');
  return { css, preload };
}
